/**
 * Generated by `createservice subscription.ActivateSubscriptionContextService --type mutations`
 */

const { GQLError, GQLErrorCode: { BAD_USER_INPUT } } = require('@open-condo/keystone/errors')
const { getLogger } = require('@open-condo/keystone/logging')
const { GQLCustomSchema, find, getById, itemsQuery } = require('@open-condo/keystone/schema')

const {
    PAYMENT_DONE_STATUS,
} = require('@condo/domains/acquiring/constants/payment')
const { freezePaymentInfo } = require('@condo/domains/acquiring/utils/billingFridge')
const { INVOICE_STATUS_PAID } = require('@condo/domains/marketplace/constants')
const access = require('@condo/domains/subscription/access/ActivateSubscriptionContextService')
const {
    PERIOD_TO_MONTHS,
    SUBSCRIPTION_CONTEXT_STATUS,
    SUBSCRIPTION_CONTEXT_STATUS_TRANSITIONS,
    SUBSCRIPTION_PAYMENT_TYPE_CARD,
    SUBSCRIPTION_PAYMENT_TYPE_INVOICE,
} = require('@condo/domains/subscription/constants')
const { SubscriptionContext } = require('@condo/domains/subscription/utils/serverSchema')
const { calculateSubscriptionPeriod } = require('@condo/domains/subscription/utils/subscriptionContext')

const logger = getLogger('ActivateSubscriptionContextService')

const ERRORS = {
    SUBSCRIPTION_CONTEXT_NOT_FOUND: {
        mutation: 'activateSubscriptionContext',
        variable: ['data', 'subscriptionContext'],
        code: BAD_USER_INPUT,
        type: 'SUBSCRIPTION_CONTEXT_NOT_FOUND',
        message: 'SubscriptionContext not found',
    },
    SUBSCRIPTION_CONTEXT_INVALID_STATUS: {
        mutation: 'activateSubscriptionContext',
        variable: ['data', 'subscriptionContext'],
        code: BAD_USER_INPUT,
        type: 'SUBSCRIPTION_CONTEXT_INVALID_STATUS',
        message: 'SubscriptionContext must have status CREATED or PENDING',
    },
    PRICING_RULE_NOT_FOUND: {
        mutation: 'activateSubscriptionContext',
        variable: ['data', 'subscriptionContext'],
        code: BAD_USER_INPUT,
        type: 'PRICING_RULE_NOT_FOUND',
        message: 'Pricing rule not found for SubscriptionContext',
    },
    INVOICE_NOT_FOUND: {
        mutation: 'activateSubscriptionContext',
        variable: ['data', 'subscriptionContext'],
        code: BAD_USER_INPUT,
        type: 'INVOICE_NOT_FOUND',
        message: 'Invoice not found for SubscriptionContext',
    },
    INVOICE_NOT_PAID: {
        mutation: 'activateSubscriptionContext',
        variable: ['data', 'subscriptionContext'],
        code: BAD_USER_INPUT,
        type: 'INVOICE_NOT_PAID',
        message: 'Invoice is not paid',
    },
}

const ActivateSubscriptionContextService = new GQLCustomSchema('ActivateSubscriptionContextService', {
    types: [
        {
            access: true,
            type: 'input ActivateSubscriptionContextInput { dv: Int!, sender: SenderFieldInput!, subscriptionContext: SubscriptionContextWhereUniqueInput! }',
        },
        {
            access: true,
            type: 'type ActivateSubscriptionContextOutput { subscriptionContext: SubscriptionContext }',
        },
    ],

    mutations: [
        {
            access: access.canActivateSubscriptionContext,
            schema: 'activateSubscriptionContext(data: ActivateSubscriptionContextInput!): ActivateSubscriptionContextOutput',
            doc: {
                summary: 'Activates a subscription context whose invoice is paid: resolves the payment method (if any), sets status to DONE and recomputes startAt/endAt so the paid period starts at payment time rather than registration time.',
                errors: ERRORS,
            },
            resolver: async (parent, args, context) => {
                const { data } = args
                const { dv, sender, subscriptionContext: subscriptionContextInput } = data

                logger.info({ msg: 'Starting subscription context activation', data: { subscriptionContextId: subscriptionContextInput.id } })

                const [subscriptionContext] = await find('SubscriptionContext', {
                    id: subscriptionContextInput.id,
                    deletedAt: null,
                })
                if (!subscriptionContext) {
                    logger.warn({ msg: 'SubscriptionContext not found', data: { subscriptionContextId: subscriptionContextInput.id } })
                    throw new GQLError(ERRORS.SUBSCRIPTION_CONTEXT_NOT_FOUND, context)
                }
                logger.info({ msg: 'Found subscription context', data: { subscriptionContextId: subscriptionContext.id, status: subscriptionContext.status, invoiceId: subscriptionContext.invoice } })

                if (!SUBSCRIPTION_CONTEXT_STATUS_TRANSITIONS[subscriptionContext.status]?.includes(SUBSCRIPTION_CONTEXT_STATUS.DONE)) {
                    logger.warn({ msg: 'SubscriptionContext has invalid status', data: { subscriptionContextId: subscriptionContext.id, status: subscriptionContext.status } })
                    throw new GQLError(ERRORS.SUBSCRIPTION_CONTEXT_INVALID_STATUS, context)
                }

                const pricingRule = subscriptionContext.subscriptionPlanPricingRule
                    ? await getById('SubscriptionPlanPricingRule', subscriptionContext.subscriptionPlanPricingRule)
                    : null
                const periodMonths = PERIOD_TO_MONTHS[pricingRule?.period]
                if (!periodMonths) {
                    logger.warn({ msg: 'Pricing rule not found for subscription context', data: { subscriptionContextId: subscriptionContext.id, pricingRuleId: subscriptionContext.subscriptionPlanPricingRule } })
                    throw new GQLError(ERRORS.PRICING_RULE_NOT_FOUND, context)
                }

                if (!subscriptionContext.invoice) {
                    logger.warn({ msg: 'SubscriptionContext has no invoice', data: { subscriptionContextId: subscriptionContext.id } })
                    throw new GQLError(ERRORS.INVOICE_NOT_FOUND, context)
                }
                const [invoice] = await find('Invoice', {
                    id: subscriptionContext.invoice,
                    deletedAt: null,
                })
                if (!invoice) {
                    logger.warn({ msg: 'Invoice not found', data: { invoiceId: subscriptionContext.invoice } })
                    throw new GQLError(ERRORS.INVOICE_NOT_FOUND, context)
                }
                logger.info({ msg: 'Found invoice', data: { invoiceId: invoice.id, status: invoice.status } })

                if (invoice.status !== INVOICE_STATUS_PAID) {
                    logger.warn({ msg: 'Invoice is not paid', data: { invoiceId: invoice.id, status: invoice.status } })
                    throw new GQLError(ERRORS.INVOICE_NOT_PAID, context)
                }

                const payments = await itemsQuery('Payment', {
                    where: {
                        invoice: { id: invoice.id, deletedAt: null },
                        status: PAYMENT_DONE_STATUS,
                        deletedAt: null,
                    },
                    sortBy: ['createdAt_DESC'],
                })
                const payment = payments[0]

                let multiPayment = null
                if (payment && payment.multiPayment) {
                    const [foundMultiPayment] = await find('MultiPayment', {
                        id: payment.multiPayment,
                        deletedAt: null,
                    })
                    multiPayment = foundMultiPayment || null
                }
                logger.info({ msg: 'Resolved payment method for invoice', data: { invoiceId: invoice.id, paymentCount: payments.length, multiPaymentId: multiPayment?.id || null } })

                const paymentMethod = multiPayment?.meta?.paymentMethod || null
                const bindingId = paymentMethod?.bindingId || null
                const frozenPaymentInfo = {
                    ...freezePaymentInfo(multiPayment, invoice, subscriptionContext.subscriptionPlanPricingRule),
                    // how the organization chose to pay when it registered, contexts created before it was recorded read it off the payment
                    paymentType: subscriptionContext.frozenPaymentInfo?.paymentType
                        || (multiPayment ? SUBSCRIPTION_PAYMENT_TYPE_CARD : SUBSCRIPTION_PAYMENT_TYPE_INVOICE),
                }

                const existingDoneContexts = await find('SubscriptionContext', {
                    organization: { id: subscriptionContext.organization },
                    subscriptionPlan: { id: subscriptionContext.subscriptionPlan },
                    status: SUBSCRIPTION_CONTEXT_STATUS.DONE,
                    deletedAt: null,
                })
                const { startAt, endAt } = calculateSubscriptionPeriod(existingDoneContexts, periodMonths)

                logger.info({ msg: 'Updating subscription context', data: { subscriptionContextId: subscriptionContext.id, bindingId, hasPaymentMethod: !!paymentMethod, startAt, endAt } })

                await SubscriptionContext.update(context, subscriptionContext.id, {
                    dv,
                    sender,
                    status: SUBSCRIPTION_CONTEXT_STATUS.DONE,
                    startAt,
                    endAt,
                    bindingId,
                    frozenPaymentInfo,
                })

                const updatedSubscriptionContext = await getById('SubscriptionContext', subscriptionContext.id)
                logger.info({ msg: 'Subscription context activated successfully', data: { subscriptionContextId: subscriptionContext.id, status: updatedSubscriptionContext.status, bindingId: updatedSubscriptionContext.bindingId } })

                return { subscriptionContext: updatedSubscriptionContext }
            },
        },
    ],
})

module.exports = {
    ActivateSubscriptionContextService,
    ERRORS,
}
